#!/usr/bin/env node
'use strict'
const fs = require('node:fs')

function cells(line) {
  const out = []
  let cell = ''
  let quoted = false
  for (const char of line) {
    if (char === '"') quoted = !quoted
    else if (char === ',' && !quoted) {
      out.push(cell)
      cell = ''
    } else cell += char
  }
  out.push(cell)
  return out.map(text => text.trim())
}

function main(file, column) {
  const lines = fs.readFileSync(file, 'utf8').split(/\r?\n/).filter(line => line.trim() !== '')
  const header = cells(lines[0] || '')
  const at = header.indexOf(column)
  if (at === -1) {
    console.error('no column ' + column + '; the columns are: ' + header.join(', '))
    return 1
  }
  const sum = lines.slice(1).reduce((total, line) => total + parseFloat(cells(line)[at]), 0)
  console.log(String(Math.round(sum * 100) / 100))
  return 0
}

process.exitCode = main(process.argv[2], process.argv[3])

